/* ---- data/cosmetics.js ---- */
/* How Smart Are You? — The cosmetics catalogue: rarities, slots, shop sections and every item. Item ids are saved in players' inventories: never change or reuse one. Prices: c = Brain Coins, g = Brain Gems. req = how an exclusive item is earned.
   Plain script; loads before the game code (see index.html). */
/* ===== SHOP CATALOGUE =====================================================
   Every cosmetic item. Fields:
     id, slot, v (what it applies), name, desc, r (rarity: c u r e l m i),
     c = price in Brain Coins, g = price in Gems,
     req = unlock requirement: {lvl:n} | {ach:'id'} | {missions:n}
   No price + no requirement  = free, owned by everyone.
   No price + a requirement   = earned: unlocks by itself when the requirement is met.
   A price (+ maybe a requirement) = bought in the shop once the requirement is met.
   Rarity is only a label. Nothing in the shop affects scoring or difficulty.
   ========================================================================== */
const RARITY = { c: ['Common', '#9ca3af'], u: ['Uncommon', '#22c55e'], r: ['Rare', '#3b82f6'], e: ['Epic', '#a855f7'], l: ['Legendary', '#f59e0b'] };
